        w.int(v.run)
        w.string(v.title)
        w.string(v.detail)
        w.string(v.image)
        w.string(v.symbol)
        w.bool(v.browsable)
        w.bool(v.playing)
        w.float64(v.progress)
        w.bool(v.enabled)
    }

    fun readShownItem(r: AsukaNativeReader): ShownItem {
        val f0 = r.int()
        val f1 = r.string()
        val f2 = r.string()
        val f3 = r.string()
        val f4 = r.string()
        val f5 = r.bool()
        val f6 = r.bool()
        val f7 = r.float64()
        val f8 = r.bool()
        return ShownItem(run = f0, title = f1, detail = f2, image = f3, symbol = f4, browsable = f5, playing = f6, progress = f7, enabled = f8)
    }

    fun writeShownRoute(w: AsukaNativeWriter, v: ShownRoute) {
        w.int(v.run)
        w.string(v.title)
        w.string(v.detail)
        w.float64(v.distance)
        w.duration(v.time)
        Wire.writeSliceCoordinate(w, v.path)
    }

    fun readShownRoute(r: AsukaNativeReader): ShownRoute {
        val f0 = r.int()
        val f1 = r.string()
        val f2 = r.string()
        val f3 = r.float64()
        val f4 = r.duration()
        val f5 = Wire.readSliceCoordinate(r)
        return ShownRoute(run = f0, title = f1, detail = f2, distance = f3, time = f4, path = f5)
    }

    fun writeSliceCoordinate(w: AsukaNativeWriter, v: List<Coordinate>) {
        w.len(v.size)
        for (e in v) Wire.writeCoordinate(w, e)
    }

    fun readSliceCoordinate(r: AsukaNativeReader): List<Coordinate> {
        val n = r.len()
        return List(n) { Wire.readCoordinate(r) }
    }

    fun writeSliceManeuver(w: AsukaNativeWriter, v: List<Maneuver>) {
        w.len(v.size)
        for (e in v) Wire.writeManeuver(w, e)
    }

    fun readSliceManeuver(r: AsukaNativeReader): List<Maneuver> {
        val n = r.len()
        return List(n) { Wire.readManeuver(r) }
    }

    fun writeSliceMarker(w: AsukaNativeWriter, v: List<Marker>) {
        w.len(v.size)
        for (e in v) Wire.writeMarker(w, e)
    }

    fun readSliceMarker(r: AsukaNativeReader): List<Marker> {
        val n = r.len()
        return List(n) { Wire.readMarker(r) }
    }

    fun writeSliceShownItem(w: AsukaNativeWriter, v: List<ShownItem>) {
        w.len(v.size)
        for (e in v) Wire.writeShownItem(w, e)
    }

    fun readSliceShownItem(r: AsukaNativeReader): List<ShownItem> {
        val n = r.len()
        return List(n) { Wire.readShownItem(r) }
    }

    fun writeSliceShownRoute(w: AsukaNativeWriter, v: List<ShownRoute>) {
        w.len(v.size)
        for (e in v) Wire.writeShownRoute(w, e)
    }

    fun readSliceShownRoute(r: AsukaNativeReader): List<ShownRoute> {
        val n = r.len()
        return List(n) { Wire.readShownRoute(r) }
    }

    fun writeOptInt(w: AsukaNativeWriter, v: Long?) {
        w.present(v != null)
        if (v != null) w.int(v)
    }

    fun readOptInt(r: AsukaNativeReader): Long? = if (r.present()) r.int() else null

}
